INSERT INTO products ("brandId", "subId", "subName", "subColor", "subSoul", "subAdStyle", "subHashtags", "prodId", "prodName", "prodTag", "spec", "feature", "hasPackaging", "packShape", "productLook", "showContents", "contentsLook", "realSize") VALUES ('test_2570', 'test_2570_main', '主力商品', 'MH Selections色', '# TEST 品牌靈魂書  ## 1. 品牌定位宣言 **傳承台灣古早味，喚醒每一代人心中最真摯的味蕾記憶**  ## 2. 品牌靈魂 - 我們不只是製造食品，更是守護台灣味覺文化的傳承者 - 每一口都承載著阿嬤手作的溫度與時光淬煉的智慧 - 用最純粹的食材，重現最真實的台灣古早味道 - 讓忙碌現代', '### 語調特色： - **溫暖親切**：使用「阿嬤」「古早」「手作」等親近詞彙 - **懷舊情懷**：融入時代記憶與童年回憶元素 - **真誠樸實**：避免過度華麗修飾，強調真實感受', '### 中文標籤：', 'test_2570_main_p0', 'TEST', '主力商品', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO products ("brandId", "subId", "subName", "subColor", "subSoul", "subAdStyle", "subHashtags", "prodId", "prodName", "prodTag", "spec", "feature", "hasPackaging", "packShape", "productLook", "showContents", "contentsLook", "realSize") VALUES ('flm', 'flm_roast', '招牌烤製', 'brown', '傳統炭火工藝，外皮酥脆金紅、內裏鮮嫩多汁。每一道烤製菜式背後是師傅數十年火候經驗，精確到秒，不早不晚。', '強調皮脆肉嫩、色澤金紅、傳統手工、鑊氣十足，用視覺感官詞引發食慾，簡體中文港式語氣', '#炸子雞 #脆皮乳豬 #香港粵菜 #福臨門 #富豪飯堂', 'flm_roast_p1', '當紅炸子雞', '皮脆肉嫩・色澤金紅', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
